/**
 * The share image of a page (og:image / twitter:image, with the alt text in the page's language).
 *
 * Every page that has its own image is a key of OG in functions/_og_manifest.js (generated by `npm run og`, scripts/make-og-images.mjs):
 * the app page in 26 languages, the 32 price pages of the countries in their language, and the main Danish pages. Any other page (the city
 * pages, an unknown path) gets the one generic /og-image.png. The files are static (/og/<page path>.png, kept off the Function by _routes.json).
 * A leading underscore keeps this file out of Pages' route table.
 */
import { OG } from './_og_manifest.js';

export const OG_ORIGIN = 'https://elpriser.org';
export const OG_GENERIC = '/og-image.png';
const GENERIC_ALT = 'Elpriser: aktuelle elpriser for Danmark, DK1 Vest og DK2 Øst, time for time.';

/** { url, alt } for a page path: its own image, or (the net companies' pages /dk1/<slug>) its price area's, or the generic one. */
export function ogFor(pathname) {
  const area = /^\/(dk[12])\/[a-z0-9-]+$/.exec(pathname);
  const hit = OG[pathname] || (area && OG['/' + area[1]]);
  // ?v= is a hash of what the picture is drawn from: a regenerated image is a new URL, so the share crawlers' caches do not keep the old one.
  return hit ? { url: `${OG_ORIGIN}${hit.f}?v=${hit.v}`, alt: hit.alt, own: true } : { url: OG_ORIGIN + OG_GENERIC, alt: GENERIC_ALT, own: false };
}

const attr = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

/** The four tags of the template (index.html carries them for the front page) written for this page. */
export function withOgImage(html, pathname) {
  const { url, alt } = ogFor(pathname), a = attr(alt);
  const set = (re, tag) => { html = html.replace(re, () => tag); };
  set(/<meta property="og:image" content="[^"]*">/, `<meta property="og:image" content="${url}">`);
  set(/<meta property="og:image:alt" content="[^"]*">/, `<meta property="og:image:alt" content="${a}">`);
  set(/<meta name="twitter:image" content="[^"]*">/, `<meta name="twitter:image" content="${url}">`);
  set(/<meta name="twitter:image:alt" content="[^"]*">/, `<meta name="twitter:image:alt" content="${a}">`);
  return html;
}
